   pOut[909] = -pOut[463]*si65*y + pOut[662]*si37 + rsq*si66*x*y - si111*x*y*zz;
   pOut[910] = -pOut[461]*si149 + pOut[670]*si37*z - rsq*si66*z - si150*xx*z;
