   pOut[915] = -pOut[461]*si65 + pOut[675]*si37*z + rsq*si66*z + si107*yy*z + si110*xx*z;
   pOut[916] = -pOut[463]*si65 + pOut[665]*si37 + rsq*si66*x + si107*x*yy - si111*x*zz;
   pOut[917] = -pOut[461]*si65 - pOut[468]*si108*z + pOut[668]*si109 + pOut[677]*si37*z;
   pOut[918] = -si153*x*y*z;
   pOut[919] = -pOut[468]*si65*y + pOut[667]*si37 + rsq*si66*y + si110*xx*y - si111*y*zz;
   pOut[920] = -pOut[480]*rsq*si34 + pOut[680]*si35*z;
   pOut[921] = -pOut[480]*si64*x - pOut[481]*rsq*si34 + pOut[681]*si35*z;
   pOut[922] = -pOut[480]*si64*y - pOut[482]*rsq*si34 + pOut[682]*si35*z;
