         OsrrB_3cKerM_x(&pOut_[19*nCompA_Out], &pMem[19*nCompA], fPmQx, la, lab, i2ze);
         OsrrB_3cKerM_z(&pOut_[20*nCompA_Out], &pMem[17*nCompA], fPmQz, la, lab, i2ze);
