      pOut[so*5] = pIn[8]*sd3d + sd3a*z14 + sd3a*z7 + sd3b*z19 - sd3c*z11 - sd3c*z1a;
      pOut[so*6] = pIn[2] - sd3e*z0 - sd3e*z1 - sd3f*z9 - sd3f*zb + sd40*za + sd40*zd + sd41*z1b - sd42*zc - sd42*ze;
      pOut[so*7] = pIn[6]*sd3d + sd3a*z13 + sd3a*z5 + sd3b*z17 - sd3c*z10 - sd3c*z18;
      pOut[so*8] = -sd36*za + sd36*zc + sd36*zd - sd36*ze + sd43*z0 - sd43*z1 + sd43*z9 - sd43*zb;
      pOut[so*9] = sd32*z13 + sd33*z17 - sd34*z18 - sd35*z5 + sd36*z10;
      pOut[so*10] = -sd44*z0 - sd44*z1 + sd45*z9 + sd45*zb + sd46*za + sd46*zd - sd47*z1b;
      pOut[so*11] = sd2d*z13 - sd2e*z17 + sd2f*z5;
      pOut[so*12] = sd48*z0 - sd48*z1 - sd49*z9 + sd49*zb;
      pOut += 13*so;
