      pOut[so*4] = pIn[6]*sd5 + sd22*z1 + sd22*z5 + sd23*zb - sd24*z13 - sd24*zc;
      pOut[so*5] = pIn[2] + sd25*z7 + sd25*z8 + sd26*z14 - sd27*zd - sd27*ze;
      pOut[so*6] = pIn[4]*sd5 + sd22*z0 + sd22*z3 + sd23*z9 - sd24*z12 - sd24*za;
      pOut[so*7] = sd20*zd - sd20*ze - sd28*z7 + sd28*z8;
      pOut[so*8] = sd1b*z3 + sd1c*z9 - sd1d*z12 - sd1e*z0 + sd1f*za;
