               T[4+sd*2] = -2*a0_101 + a1_103;
               T[5+sd*2] = a1_211;
               T[6+sd*2] = -2*a0_011 + a1_013;
               T[7+sd*2] = -a0_200 + a1_202;
               T[8+sd*2] = -a0_020 + a1_022;
               T[9+sd*2] = -a0_110 + a1_112;
